diff --git a/lib/rules/no-unused-expressions.js b/lib/rules/no-unused-expressions.js
index 6529c0a..87f5a4c 100644
--- a/lib/rules/no-unused-expressions.js
+++ b/lib/rules/no-unused-expressions.js
@@ -83,6 +83,56 @@ module.exports = {
 			},
 		] = context.options;

+		/**
+		 * Has AST suggesting a directive.
+		 * @param {ASTNode} node any node
+		 * @returns {boolean} whether the given node structurally represents a directive
+		 */
+		function looksLikeDirective(node) {
+			return (
+				node.type === "ExpressionStatement" &&
+				node.expression.type === "Literal" &&
+				typeof node.expression.value === "string"
+			);
+		}
+
+		/**
+		 * Detect if a Node is a directive.
+		 * `node.directive` is not set by parsers when `ecmaVersion` is 3,
+		 * so the directive prologue is detected structurally.
+		 * @param {ASTNode} node any node
+		 * @returns {boolean} whether the given node is considered a directive in its current position
+		 */
+		function isDirective(node) {
+			if (astUtils.isDirective(node)) {
+				return true;
+			}
+
+			/**
+			 * https://tc39.es/ecma262/#directive-prologue
+			 *
+			 * Only `FunctionBody`, `ScriptBody` and `ModuleBody` can have directive prologue.
+			 * Class static blocks do not have directive prologue.
+			 */
+			if (
+				!looksLikeDirective(node) ||
+				!astUtils.isTopLevelExpressionStatement(node)
+			) {
+				return false;
+			}
+
+			for (const statement of node.parent.body) {
+				if (statement === node) {
+					return true;
+				}
+				if (!looksLikeDirective(statement)) {
+					return false;
+				}
+			}
+
+			return false;
+		}
+
 		/**
 		 * The member functions return `true` if the type has no side-effects.
 		 * Unknown nodes are handled as `false`, then this rule ignores those.
@@ -154,7 +204,7 @@ module.exports = {
 			ExpressionStatement(node) {
 				if (
 					Checker.isDisallowed(node.expression) &&
-					!astUtils.isDirective(node)
+					!isDirective(node)
 				) {
 					context.report({ node, messageId: "unusedExpression" });
 				}
diff --git a/repro/no-unused-expressions-es3.js b/repro/no-unused-expressions-es3.js
new file mode 100644
index 0000000..0d34d2c
--- /dev/null
+++ b/repro/no-unused-expressions-es3.js
@@ -0,0 +1,30 @@
+/* eslint no-console: "off" -- repro script output */
+"use strict";
+
+// Repro: `no-unused-expressions` reports `'use strict'` with `ecmaVersion: 3` (9.25.0 regression).
+const { Linter } = require("../lib/api");
+const code =
+	"'use strict';\nfunction f() { 'use strict'; return 1; }\nf(); 'not a directive';\n";
+let failed = false;
+
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const messages = new Linter().verify(
+		code,
+		[
+			{
+				languageOptions: { ecmaVersion, sourceType: "script" },
+				rules: { "no-unused-expressions": "error" },
+			},
+		],
+		"x.js",
+	);
+	const lines = JSON.stringify(messages.map(m => m.line));
+
+	console.log(
+		`ecmaVersion ${ecmaVersion}: reported lines ${lines} (expected [3])`,
+	);
+	if (lines !== "[3]") {
+		failed = true;
+	}
+}
+process.exitCode = failed ? 1 : 0;
